import{c as e,Q as d,j as o,m as r}from"./chunks/framework.CNW5BFKi.js";const g=JSON.parse('{"title":"Design: 增加国内赛事与丰富趣闻轶事","description":"","frontmatter":{"comet_change":"add-cn-races-stories","role":"technical-design","canonical_spec":"openspec"},"headers":[],"relativePath":"superpowers/specs/2026-05-30-add-cn-races-stories-design.md","filePath":"superpowers/specs/2026-05-30-add-cn-races-stories-design.md"}'),a={name:"superpowers/specs/2026-05-30-add-cn-races-stories-design.md"};function c(s,t,i,n,l,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="design-增加国内赛事与丰富趣闻轶事" tabindex="-1">Design: 增加国内赛事与丰富趣闻轶事 <a class="header-anchor" href="#design-增加国内赛事与丰富趣闻轶事" aria-label="Permalink to &quot;Design: 增加国内赛事与丰富趣闻轶事&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>对马拉松百科站点做三项内容调整：增加国内赛事区块、丰富趣闻轶事、移除传奇人物栏目。</p><h2 id="技术方案" tabindex="-1">技术方案 <a class="header-anchor" href="#技术方案" aria-label="Permalink to &quot;技术方案&quot;">​</a></h2><h3 id="_1-racecardgrid-组件-—-href-可选化" tabindex="-1">1. RaceCardGrid 组件 — href 可选化 <a class="header-anchor" href="#_1-racecardgrid-组件-—-href-可选化" aria-label="Permalink to &quot;1. RaceCardGrid 组件 — href 可选化&quot;">​</a></h3><p><strong>改动</strong>：<code>RaceCardGrid.vue</code> 的 <code>Race</code> 接口中 <code>href</code> 从必填改为可选。</p><p><strong>渲染逻辑</strong>：有 <code>href</code> 时渲染 <code>&lt;a&gt;</code> 标签（可点击跳转），无 <code>href</code> 时渲染 <code>&lt;div&gt;</code>（纯展示卡片）。使用 <code>v-if/v-else</code> 分支，样式复用 <code>.race-card</code> 类，移除无链接卡片的 <code>cursor: pointer</code>。</p><h3 id="_2-国内赛事区块" tabindex="-1">2. 国内赛事区块 <a class="header-anchor" href="#_2-国内赛事区块" aria-label="Permalink to &quot;2. 国内赛事区块&quot;">​</a></h3><p><strong>位置</strong>：在 <code>majors.md</code> 页面「六星跑者」区块之后，新增 <code>## 国内知名赛事</code> 二级标题。</p><p><strong>数据</strong>：5 场赛事，复用 <code>&lt;RaceCardGrid&gt;</code> 组件：</p><table tabindex="0"><thead><tr><th>赛事</th><th>地点</th><th>描述</th></tr></thead><tbody><tr><td>十堰马拉松</td><td>湖北十堰</td><td>武当山脚下的特色赛事</td></tr><tr><td>武汉马拉松</td><td>湖北武汉</td><td>华中地区最大规模马拉松，横跨长江大桥</td></tr><tr><td>北京马拉松</td><td>北京</td><td>国内历史最悠久的马拉松赛事，始于1981年</td></tr><tr><td>上海马拉松</td><td>上海</td><td>国际田联金标赛事，中国最大规模马拉松之一</td></tr><tr><td>厦门马拉松</td><td>福建厦门</td><td>海滨赛道，风景优美</td></tr></tbody></table><p><strong>图片</strong>：暂无 SVG 资源，<code>image</code> 字段不设，RaceCardGrid 已处理空 image（显示 <code>--color-bg</code> 背景色占位）。</p><p><strong>columns</strong>：设为 5，与上方六大满贯的 3 列布局形成视觉区分。</p><h3 id="_3-趣闻轶事扩充" tabindex="-1">3. 趣闻轶事扩充 <a class="header-anchor" href="#_3-趣闻轶事扩充" aria-label="Permalink to &quot;3. 趣闻轶事扩充&quot;">​</a></h3><p>从 2 条扩充到 7 条，新增 5 条：</p><table tabindex="0"><thead><tr><th>#</th><th>标题</th><th>内容</th></tr></thead><tbody><tr><td>1</td><td>最年长完赛者</td><td>现有，保持不变</td></tr><tr><td>2</td><td>最有趣的装扮</td><td>现有，保持不变</td></tr><tr><td>3</td><td>赤脚夺金</td><td>1960年罗马奥运会，埃塞俄比亚选手阿贝贝·比基拉赤脚跑完全程夺得金牌，震惊世界</td></tr><tr><td>4</td><td>首位正式参赛的女性</td><td>1967年波士顿马拉松，凯瑟琳·斯威策以&quot;K.V. Switzer&quot;报名参赛，成为首位正式参赛的女性跑者</td></tr><tr><td>5</td><td>推着跑的父亲</td><td>迪克·霍伊特推着患有脑瘫的儿子里克，共同完成了超过1000场耐力赛事</td></tr><tr><td>6</td><td>心碎坡的由来</td><td>波士顿马拉松32公里处的&quot;心碎坡&quot;得名于1936年，当时选手在此被对手甩开，&quot;心碎&quot;一词沿用至今</td></tr><tr><td>7</td><td>马拉松距离的由来</td><td>1908年伦敦奥运会，为让皇室从温莎城堡观看起跑，将距离定为42.195公里，此后成为标准</td></tr></tbody></table><p><strong>图片</strong>：暂无新 SVG，新增条目 <code>image</code> 字段不设。</p><h3 id="_4-传奇人物移除" tabindex="-1">4. 传奇人物移除 <a class="header-anchor" href="#_4-传奇人物移除" aria-label="Permalink to &quot;4. 传奇人物移除&quot;">​</a></h3><p>清理路径：</p><ol><li>删除 <code>docs/legends/male.md</code>、<code>docs/legends/female.md</code> 及 <code>docs/legends/</code> 目录</li><li>从 <code>.vitepress/config.ts</code> nav 移除 <code>{ text: &#39;传奇人物&#39;, link: &#39;/legends/male&#39; }</code></li><li>从 <code>.vitepress/theme/index.ts</code> 移除 <code>LegendPortrait</code> 的 import 和 <code>app.component</code> 注册</li><li>删除 <code>.vitepress/theme/components/LegendPortrait.vue</code></li><li>保留 <code>docs/public/images/legends/</code> 图片目录（不影响运行，后续可清理）</li></ol><h2 id="风险" tabindex="-1">风险 <a class="header-anchor" href="#风险" aria-label="Permalink to &quot;风险&quot;">​</a></h2><ul><li><strong>图片缺失</strong>：国内赛事和新增趣闻暂无 SVG，显示为纯色背景占位，不影响功能</li><li><strong>proposal 修正</strong>：proposal 原文说&quot;不修改组件代码&quot;，实际需修改 RaceCardGrid，需更新 proposal 非目标条目</li></ul><h2 id="测试策略" tabindex="-1">测试策略 <a class="header-anchor" href="#测试策略" aria-label="Permalink to &quot;测试策略&quot;">​</a></h2><p><code>npm run dev</code> 启动后手动验证：</p><ul><li>国内赛事区块正确渲染 5 张卡片，无链接的卡片为 div 元素</li><li>趣闻轶事页面显示 7 条故事</li><li>传奇人物导航入口消失</li><li>无控制台报错</li></ul>',25)])])}const u=e(a,[["render",c]]);export{g as __pageData,u as default};
